                    alamat: "",
                    kota: "",
                    provinsi: "",
                    kode_pos: "",
                    dosen_wali_id: "",
                    parent_name: "",
                    parent_phone: "",
                    parent_job: "",
                    parent_address: "",
                    parent_email: "",
                    parent_rt: "",
                    parent_rw: "",
                    parent_kota: "",
                    parent_provinsi: "",
                    parent_kode_pos: "",
                    parent_negara: "",
                    kewarganegaraan: "",
                    rt: "",
                    rw: "",
                    dusun: "",
                    kelurahan: "",
                    kecamatan: "",
                    kode_wilayah: "",
                    jenis_tinggal_id: "",
                    jenis_tinggal: "",
