                    no_kk: "",
                    npwp: "",
                    no_kip: "",
                    no_kps: "",
                    kebutuhan_khusus: "",
                    tinggi_badan: "",
                    berat_badan: "",
                    semester_masuk: "",
                    tanggal_masuk: "",
                    jenis_pendaftaran_id: "",
                    jenis_pendaftaran: "",
                    jalur_masuk_id: "",
                    jalur_masuk: "",
